def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_defects = 0
    opp_defects = 0
    for m, o in history:
        if m == 'D':
            my_defects += 1
        if o == 'D':
            opp_defects += 1

    last_my, last_opp = history[-1]

    # Detect retaliation to our unprovoked defection
    retaliated = False
    for i in range(n - 1):
        if history[i][0] == 'D' and history[i][1] == 'C' and history[i+1][1] == 'D':
            retaliated = True
            break

    # Always defect on the last round
    if n == 99:
        return 'D'

    # If opponent never retaliated to our unprovoked defections, use proactive defection schedule
    if not retaliated:
        if n in (9, 21, 33, 45, 57, 69, 81, 93):
            return 'D'

    # Handle opponent's last action
    if last_opp == 'C':
        return 'C'

    # Opponent defected last round
    if last_my == 'C':
        # Opponent defected while we cooperated
        if n < 3:
            return 'D'
        if opp_defects <= max(1, n // 10):
            return 'C'
        else:
            return 'D'
    else:
        # Both defected last round (DD cycle)
        if opp_defects > n * 0.3:
            return 'D'
        else:
            return 'C'
